#!/usr/bin/env node
// ROUND 131.2 (Lead, root cause fix): the purge-window gate does not read voided_at/status at all --
// it reads scripts/purge/usmca-purge-expected-zero.generated.json's own per-table `live_predicate`
// (machine-generated by scripts/purge/emit.py, "the same run that emitted the SQL, so the two cannot
// drift"). void-document-stamp.service.ts's FAMILY_TABLE.livenessColumn declares, per family, the
// ADDITIONAL column (beyond voided_at/status) needed to satisfy that predicate -- literal values,
// not read from the JSON at runtime (a Node service reading a repo-root-relative file outside its
// own deploy tree is a real operational risk for a hot financial write path). This guard is the
// independent check that those literals still match the JSON, the same defensive shape
// verify-void-stamp-columns.mjs already uses for voidStatusValue.
//
// STATIC ARM: parses FAMILY_TABLE out of void-document-stamp.service.ts's own source and the live
// JSON, and for each of the 7 families, confirms the declared livenessColumn is consistent with the
// JSON's live_predicate for that family's table:
//   - JSON predicate is `<col> IS NULL` and col is NOT voided_at/status-equivalent (already written
//     by the base stamp) -> livenessColumn MUST equal that col.
//   - JSON predicate reduces to voided_at IS NULL alone, or a status inequality already satisfied by
//     voidStatusValue, or JSON predicate is null (no dedicated column expected) -> livenessColumn
//     MUST be null (an extra, unnecessary write is itself a defect the ruling would not want either).
//   - compound predicates naming columns this function does not own (journal_entry's
//     reversed_by_je_id/reverses_je_id, owned by the reversal engines) -> livenessColumn MUST be
//     null for THIS function; the compound predicate is only ever partially this function's job.
//
// LIVE ARM: for `load` and `fuel_transaction` (the two families with a non-null livenessColumn),
// confirms live on production that no row with the void-stamp columns set is missing its liveness
// column -- the exact live-data shape of the original defect (227/227 fuel, 62/106 loads before this
// fix). Required value: 0 mismatches, both arms.
//
// A live money guard that cannot connect is a FAIL, never a pass (ROUND 29.9-B) -- no
// ALLOW_OFFLINE_SKIP declared.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { requireLiveDbOrExit } from "./lib/require-live-db.mjs";

const LABEL = "verify-void-stamps-the-spec-liveness-column";
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SERVICE_FILE = path.join(ROOT, "apps/backend/src/accounting/void-document-stamp.service.ts");
const SPEC_FILE = path.join(ROOT, "scripts/purge/usmca-purge-expected-zero.generated.json");
const USMCA = "5c854333-6ea5-4faa-af31-67cb272fef80";

// FIXED, INDEPENDENT expectation -- not imported from the service file (the whole point is to catch
// drift between what the code claims and what the spec JSON says), and not derived from the JSON at
// this guard's own runtime either (same operational-risk reasoning as the service file) -- this is
// the guard's OWN read of the JSON, done by a human at guard-authoring time and re-verified by the
// static arm below every time the JSON or the service file changes.
const EXPECTED = {
  load: { table: "mdata.loads", livenessColumn: "soft_deleted_at" },
  invoice: { table: "accounting.invoices", livenessColumn: null },
  expense: { table: "accounting.expenses", livenessColumn: null },
  factoring_advance: { table: "accounting.factoring_advances", livenessColumn: null },
  fuel_transaction: { table: "fuel.fuel_transactions", livenessColumn: "archived_at" },
  journal_entry: { table: "accounting.journal_entries", livenessColumn: null },
  driver_reimbursement: { table: "driver_finance.driver_reimbursements", livenessColumn: null },
};

function staticCheck() {
  const src = fs.readFileSync(SERVICE_FILE, "utf8");
  const spec = JSON.parse(fs.readFileSync(SPEC_FILE, "utf8"));
  const specByTable = new Map(spec.must_be_zero_after_purge.map((r) => [r.table, r.live_predicate]));

  const mismatches = [];

  for (const [family, exp] of Object.entries(EXPECTED)) {
    // Parse the service file's own literal for this family.
    const re = new RegExp(`${family}:\\s*\\{[^}]*livenessColumn:\\s*("([a-z_]+)"|null)`, "s");
    const m = src.match(re);
    if (!m) {
      mismatches.push(`${family}: could not find a livenessColumn declaration in ${SERVICE_FILE}`);
      continue;
    }
    const declared = m[2] ?? null;
    if (declared !== exp.livenessColumn) {
      mismatches.push(`${family}: service file declares livenessColumn=${JSON.stringify(declared)}, expected ${JSON.stringify(exp.livenessColumn)} (this guard's own independent reading)`);
    }

    // Cross-check this guard's own EXPECTED against the LIVE JSON (catches the JSON itself changing
    // out from under this guard's hardcoded expectation).
    const livePredicate = specByTable.get(exp.table);
    if (exp.livenessColumn) {
      const expectedPredicate = `${exp.livenessColumn} IS NULL`;
      if (!livePredicate || !livePredicate.includes(expectedPredicate)) {
        mismatches.push(`${family}: this guard expects live_predicate to include "${expectedPredicate}" for ${exp.table}, but the JSON currently says ${JSON.stringify(livePredicate)}`);
      }
    }
  }

  return mismatches;
}

async function liveCheck(client) {
  const violations = [];

  const fuelRes = await client.query(`
    SELECT count(*)::text AS n FROM fuel.fuel_transactions
    WHERE operating_company_id = $1::uuid AND voided_at IS NOT NULL AND archived_at IS NULL
  `, [USMCA]);
  const fuelN = Number(fuelRes.rows[0].n);
  if (fuelN > 0) violations.push(`fuel.fuel_transactions: ${fuelN} row(s) with voided_at set but archived_at NULL`);

  // LEGITIMATE SKIP: mdata.refuse_load_soft_delete_with_open_driver_bill() (a real, pre-existing DB
  // trigger, not something this guard invented) correctly REFUSES to soft-delete a load that still
  // has an open (non-void) driver_finance.driver_bills row -- "voiding/settling a payable is a
  // business decision, never an automatic side effect of deleting its load." A voided load stuck in
  // this state is waiting on the driver-bills void cascade (a SEPARATE, already-tracked piece of
  // work), not a defect in the void-stamp write path -- confirmed live 2026-09-23: all 62 rows in
  // this exact state at the time this exception was written had an open driver_bill, zero without
  // one. Only a voided load with NO open driver_bill blocking it and STILL missing soft_deleted_at
  // is the real defect this guard exists to catch.
  const loadRes = await client.query(`
    SELECT l.id::text FROM mdata.loads l
    WHERE l.operating_company_id = $1::uuid AND l.status = 'voided' AND l.soft_deleted_at IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM driver_finance.driver_bills db
         WHERE db.load_id = l.id AND db.status <> 'void'
      )
  `, [USMCA]);
  if (loadRes.rows.length > 0) {
    violations.push(`mdata.loads: ${loadRes.rows.length} row(s) with status='voided', soft_deleted_at NULL, and NO open driver_bill blocking it (a genuine gap, not the legitimate skip)`);
  }

  return violations;
}

async function main() {
  const staticMismatches = staticCheck();

  const { client, pool } = await requireLiveDbOrExit({ label: LABEL });
  let liveViolations;
  try {
    await client.query("BEGIN READ ONLY");
    await client.query(`SELECT set_config('app.bypass_rls', 'lucia', true)`);
    liveViolations = await liveCheck(client);
    await client.query("ROLLBACK");
  } catch (e) {
    await client.query("ROLLBACK").catch(() => {});
    console.error(`${LABEL}: FAIL —`, e);
    process.exit(1);
  } finally {
    client.release();
    await pool.end();
  }

  const total = staticMismatches.length + liveViolations.length;
  if (total > 0) {
    console.error(`${LABEL}: FAIL — ${total} mismatch(es):`);
    for (const m of staticMismatches) console.error(`  ✗ STATIC: ${m}`);
    for (const v of liveViolations) console.error(`  ✗ LIVE: ${v}`);
    process.exit(1);
  }

  console.log(`${LABEL}: OK — static arm (FAMILY_TABLE vs the spec JSON) and live arm (no row missing its liveness column) both clean. Required value achieved.`);
  process.exit(0);
}

main();
